export const dynamic = 'force-dynamic'

import { NextRequest, NextResponse } from 'next/server'
import { logger } from '@/lib/logger'
import bcrypt from 'bcryptjs'
import { z } from 'zod'
import { db } from '@/lib/db'
import { rateLimit, getClientIdentifier } from '@/lib/security/rateLimit'
import { hashPasswordResetToken } from '@/lib/auth/passwordRecovery'
import { sendTemplatedEmail } from '@/lib/email-templates'

// AUTO-GENERATED by api-row-sweep --apply — REVIEW these column types.
// pg returns bigint/numeric as string, timestamptz as Date; add `| null` where nullable.
interface PasswordResetTokenRow {
  id: string
  user_id: string
}

const resetSchema = z.object({
  // Raw links, including legacy links, contain 32 random bytes encoded in hex.
  // Reject the storage prefix so a database digest cannot be used as a link.
  token: z.string().regex(/^[a-f0-9]{64}$/, 'Invalid or expired reset link.'),
  password: z.string().min(8, 'Password must be at least 8 characters'),
})

export async function POST(req: NextRequest) {
  try {
    const body: unknown = await req.json().catch(() => ({}))
    const parsed = resetSchema.safeParse(body)
    if (!parsed.success) {
      return NextResponse.json({ error: parsed.error.issues[0]?.message || 'Invalid input' }, { status: 400 })
    }

    const identifier = getClientIdentifier(req)
    const { allowed } = await rateLimit(`reset:${identifier}`, 10, 15 * 60 * 1000)
    if (!allowed) {
      return NextResponse.json({ error: 'Too many requests. Please try again later.' }, { status: 429 })
    }

    const { token, password } = parsed.data

    const passwordHash = await bcrypt.hash(password, 12)
    const account = await db.transaction(async (client) => {
      // The lock and expiry/use checks must share the password transaction.
      // The raw lookup keeps already-issued one-hour links compatible.
      const tokenRes = await client.query<PasswordResetTokenRow>(
        `SELECT id, user_id FROM password_reset_tokens
         WHERE token IN ($1, $2) AND used_at IS NULL AND expires_at > NOW()
         LIMIT 1 FOR UPDATE`,
        [hashPasswordResetToken(token), token],
      )
      const tokenRow = tokenRes.rows[0]
      if (!tokenRow) return null
      await client.query<{ set_config: string }>(
        `SELECT set_config('request.user_id', $1, true), set_config('app.current_user_id', $1, true)`,
        [tokenRow.user_id],
      )
      const updated = await client.query<{ email: string; full_name: string | null }>(
        `UPDATE users SET password_hash = $1, session_version = session_version + 1,
                         email_verified = TRUE, updated_at = NOW()
         WHERE id = $2 RETURNING email, full_name`,
        [passwordHash, tokenRow.user_id],
      )
      if (!updated.rows[0]) throw new Error('Reset account no longer exists')
      await client.query<never>(
        'UPDATE password_reset_tokens SET used_at = NOW() WHERE user_id = $1 AND used_at IS NULL',
        [tokenRow.user_id],
      )
      return updated.rows[0]
    })
    if (!account) return NextResponse.json({ error: 'Invalid or expired reset link.' }, { status: 400 })

    // A notification failure cannot undo an already committed password change.
    const notification = await sendTemplatedEmail('passwordChanged', {
      to: account.email, name: account.full_name || '',
    }).catch(() => ({ success: false }))
    return NextResponse.json({ success: true, confirmationEmailSent: notification.success })
  } catch (err) {
    logger.error('[reset-password] Error:', { error: err })
    return NextResponse.json({ error: 'Failed to reset password' }, { status: 500 })
  }
}
